import { test, expect } from '@playwright/test';

test.describe('ARIA Landmarks - Page Regions', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to a page with proper ARIA landmarks
    await page.goto('data:text/html,<html><body>' +
      '<header role="banner"><h1>Website Header</h1></header>' +
      '<nav role="navigation" aria-label="Main Navigation"><ul><li><a href="#home">Home</a></li><li><a href="#about">About</a></li></ul></nav>' +
      '<main role="main"><h2>Main Content</h2><p>This is the main content area.</p></main>' +
      '<aside role="complementary" aria-label="Sidebar"><h3>Related Links</h3><ul><li><a href="#link1">Link 1</a></li></ul></aside>' +
      '<footer role="contentinfo"><p>&copy; 2024 Example Site</p></footer>' +
      '</body></html>');
  });

  test('should identify banner landmark region', async ({ page }) => {
    const banner = page.getByRole('banner');
    await expect(banner).toBeVisible();

    const heading = banner.getByRole('heading', { level: 1 });
    await expect(heading).toHaveText('Website Header');
  });

  test('should identify navigation landmark region', async ({ page }) => {
    const navigation = page.getByRole('navigation', { name: 'Main Navigation' });
    await expect(navigation).toBeVisible();

    const homeLink = navigation.getByRole('link', { name: 'Home' });
    await expect(homeLink).toBeVisible();

    const aboutLink = navigation.getByRole('link', { name: 'About' });
    await expect(aboutLink).toBeVisible();
  });

  test('should identify main content landmark region', async ({ page }) => {
    const main = page.getByRole('main');
    await expect(main).toBeVisible();

    const heading = main.getByRole('heading', { level: 2 });
    await expect(heading).toHaveText('Main Content');
  });

  test('should identify complementary landmark region', async ({ page }) => {
    const complementary = page.getByRole('complementary', { name: 'Sidebar' });
    await expect(complementary).toBeVisible();

    const heading = complementary.getByRole('heading', { level: 3 });
    await expect(heading).toHaveText('Related Links');
  });

  test('should identify contentinfo landmark region', async ({ page }) => {
    const contentinfo = page.getByRole('contentinfo');
    await expect(contentinfo).toBeVisible();

    const text = contentinfo.getByText(/© 2024 Example Site/);
    await expect(text).toBeVisible();
  });

  test('should have all major landmarks present on page', async ({ page }) => {
    const banner = page.getByRole('banner');
    const navigation = page.getByRole('navigation');
    const main = page.getByRole('main');
    const complementary = page.getByRole('complementary');
    const contentinfo = page.getByRole('contentinfo');

    await expect(banner).toBeVisible();
    await expect(navigation).toBeVisible();
    await expect(main).toBeVisible();
    await expect(complementary).toBeVisible();
    await expect(contentinfo).toBeVisible();
  });

  test('should navigate through landmarks using keyboard', async ({ page }) => {
    // Focus on the first link in navigation
    const homeLink = page.getByRole('link', { name: 'Home' });
    await homeLink.focus();

    // Verify focus is on the link
    await expect(homeLink).toBeFocused();

    // Tab to next link
    await page.keyboard.press('Tab');
    const aboutLink = page.getByRole('link', { name: 'About' });
    await expect(aboutLink).toBeFocused();
  });

  test('should maintain landmark structure in accessibility tree', async ({ page }) => {
    // Get all landmarks
    const landmarks = await page.locator('[role="banner"], [role="navigation"], [role="main"], [role="complementary"], [role="contentinfo"]').all();

    // Verify we have at least 5 landmarks
    expect(landmarks.length).toBeGreaterThanOrEqual(5);

    // Verify each landmark is visible
    for (const landmark of landmarks) {
      await expect(landmark).toBeVisible();
    }
  });
});
